# Archived v1 generator: never overwrite reviewed film-reference artwork.
from pathlib import Path as _LegacyPath
import json as _legacy_json
_legacy_manifest = _LegacyPath(__file__).parent / 'manifest.json'
if _legacy_manifest.exists() and _legacy_json.loads(_legacy_manifest.read_text()).get('styleVersion') == 'film-reference-v2':
    raise SystemExit('v1 art generator is archived. Keep the reviewed PNGs and run scripts/integrate-reference-art.mjs instead.')

from pathlib import Path
import json, math
P=Path(__file__).parent
INK='#473c36'
def svg(body,w=1600,h=900,defs=''):
 return f'''<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 {w} {h}"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#80c4c6"/><stop offset="1" stop-color="#f9e6b6"/></linearGradient><linearGradient id="water" x2="0" y2="1"><stop stop-color="#589caa"/><stop offset="1" stop-color="#1d697c"/></linearGradient><filter id="paper"><feTurbulence type="fractalNoise" baseFrequency=".8" numOctaves="3" stitchTiles="stitch" result="noise"/><feColorMatrix in="noise" type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".065"/></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply"/></filter>{defs}</defs>{body}</svg>'''
def write(name,body,w=1600,h=900,defs=''):(P/name).write_text(svg(body,w,h,defs))
